// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to a non-zero value to avoid zero-value calls that do not change state meaningfully
        vm.assume(amount > 0);
        // Ensure amount does not cause an overflow on the first call itself, but allow high values
        vm.assume(amount <= type(uint256).max - 1);

        // Prepare sender with ether
        address sender = address(0x1234);
        vm.deal(sender, amount * 2 + 1);

        // First, make many deposits to bring depositsCount close to overflow.
        // We will make exactly type(uint256).max - 1 deposits of 1 wei each to set depositsCount = type(uint256).max - 1.
        // Then we do one more deposit of 1 wei: reference reverts (overflow), buggy increments to 0.
        // After that, we do a final deposit of 'amount' wei: reference reverts (since previous didn't happen), buggy succeeds and sets depositsCount = amount (since it was 0).
        // The invariant: if the reference's receive does not revert on the final call, depositsCount must be at least the number of successful deposits.
        // But easier: after the setup, reference should revert on the last receive, buggy should not.
        // We'll test: after the sequence, if receive doesn't revert, depositsCount must be > 0.

        uint256 initialDeposits = type(uint256).max - 1;
        // Bound initialDeposits so that total deposits don't exceed ether balance
        vm.assume(initialDeposits <= type(uint256).max / 2);

        // Perform initialDeposits deposits of 1 wei
        for (uint256 i = 0; i < initialDeposits; i++) {
            vm.prank(sender);
            (bool ok, ) = address(c).call{value: 1}("");
            // In reference, this will revert when i = type(uint256).max - 1, but we are doing only type(uint256).max - 1 times, so no overflow yet
            if (!ok) {
                // If it fails early for some reason, we stop; but assume it doesn't
                break;
            }
        }

        // Now depositsCount should be initialDeposits = type(uint256).max - 1
        // Next, try to deposit 1 wei - should revert in reference (overflow), succeed in mutant (wraps to 0)
        vm.prank(sender);
        (bool successOverflow, ) = address(c).call{value: 1}("");

        // Finally, deposit 'amount' wei
        vm.prank(sender);
        (bool successFinal, ) = address(c).call{value: amount}("");

        // Assert: if the final deposit succeeded, then depositsCount must be greater than 0
        // In reference: successFinal is false (because the previous call failed and state unchanged), so implication holds vacuously.
        // In mutant: successFinal is true, but depositsCount could be 0 if amount is very large and overflowed again, but we bounded amount <= type(uint256).max - 1 so no overflow on the final call, so depositsCount should be amount > 0.
        // So overall: !successFinal || c.depositsCount() > 0
        assertTrue(!successFinal || c.depositsCount() > 0);
    }
}

