pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        // Keep amount within a wide admissible domain: any positive value up to a large bound
        amount = bound(amount, 1, type(uint256).max);

        // Use a helper that will send Ether to the contract via receive()
        Sender sender = new Sender();
        vm.deal(address(sender), amount);

        // Try to forward Ether to c; capture whether the low-level call succeeded
        bool ok;
        try sender.sendTo(address(c), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Correct behaviour: send succeeds, depositsCount > 0
        // Buggy behaviour: send always reverts, depositsCount stays 0
        assertTrue(ok ? c.depositsCount() >= 1 : c.depositsCount() == 0);
    }
}

contract Sender {
    function sendTo(address payable target, uint256 amount) external payable returns (bool) {
        // Forward the exact amount received with this call
        (bool success, ) = target.call{value: amount}("");
        require(success, "send failed");
        return success;
    }

    receive() external payable {}
}

